  const selection=s.selecting&&!readOnly?`<div class="study-bulk-actions" role="region" aria-label="Selected items"><strong role="status">${s.selection.size} selected</strong>${this.button('select-page','Select this page')}${this.button('clear-selection','Clear selection')}${s.selection.size?(s.filter==='archived'?'':this.button('study-selection','Study selected')+this.button('teach-selection','Teach selected concepts'))+`<details><summary>Manage selected</summary>${s.filter==='archived'?'':this.button('bulk-move','Move to unit')}${this.button(s.filter==='archived'?'bulk-restore':'bulk-archive',s.filter==='archived'?'Restore selected':'Archive selected')}${this.button('bulk-delete','Delete selected')}</details>`:''}</div>`:'';
