  const rowMarkup=row=>`<article class="study-coverage-item"><div><strong>${esc(row.card.term)}</strong><p>${esc(row.card.answer)}</p><span class="muted">${esc(row.reason)}</span></div><details><summary>Adjust ${esc(row.card.term)}</summary><label for="coverage-result-${row.item.id}">My recall of ${esc(row.card.term)}</label><select id="coverage-result-${row.item.id}" name="${row.item.id}">${[['knew','Covered'],['partly','Partly covered'],['missed','Not covered']].map(([value,label])=>`<option value="${value}" ${value===row.rating?'selected':''}>${label}</option>`).join('')}</select></details></article>`;
