   s.session=result;s.activeSession=result.session.status==='active'?result.session:null;s.revealed=false;s.drafts.delete('response-'+item.id);
   const saved=result.items.find(i=>i.id===item.id);s.answerFeedback='Saved. '+nextReviewLabel(saved?.next_review,studyToday())+'.';
   s.feedback={title:item.presentation==='label'?'Diagram label':c.prompt||c.term,answer:item.presentation==='label'?c.term:c.answer,response,selfChecked:['flashcard','coverage'].includes(item.presentation),rating:saved?.rating,before:c,after:result.record||result.cards.find(x=>x.id===c.id),approximate:result.session.checking_mode==='loose'&&item.presentation==='written'};
